import { useState, useCallback, useMemo, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import {
  Button,
  Breadcrumb,
  HStack,
  VStack,
  TabBar,
  TopBar,
  TopBarAction,
  Input,
  NumberInput,
  Select,
  SectionCard,
  FormField,
  Toggle,
  Slider,
  WizardSummary,
  Tabs,
  TabList,
  Tab,
  Disclosure,
  DisclosureTrigger,
  PageShell,
  DisclosurePanel,
  SearchInput,
  Pagination,
  Table,
  StatusIndicator,
  SelectionIndicator,
  Radio,
  RadioGroup,
  type TableColumn,
  fixedColumns,
} from '@/design-system';
import type { WizardSummaryItem, WizardSectionState } from '@/design-system';
import { ComputeAdminSidebar } from '@/components/ComputeAdminSidebar';
import { useIsV2 } from '@/hooks/useIsV2';
import { useTabs } from '@/contexts/TabContext';
import { IconBell, IconEdit, IconUpload, IconExternalLink } from '@tabler/icons-react';

/* ----------------------------------------
   Types
   ---------------------------------------- */

type SectionStep = 'basic-info' | 'source' | 'specification' | 'advanced';

// Section labels for display
const SECTION_LABELS: Record<SectionStep, string> = {
  'basic-info': 'Basic information',
  source: 'Source',
  specification: 'Specification',
  advanced: 'Advanced',
};

// Section order for navigation
const SECTION_ORDER: SectionStep[] = ['basic-info', 'source', 'specification', 'advanced'];

// Tenant type for owned tenant selection
interface Tenant {
  id: string;
  name: string;
  status: 'active' | 'deactivated';
  description: string;
}

// Mock tenant data
const mockTenants: Tenant[] = [
  { id: '12345678', name: 'tenant A', status: 'active', description: '-' },
  { id: '12345679', name: 'tenant B', status: 'active', description: '-' },
  { id: '12345680', name: 'tenant C', status: 'active', description: '-' },
  { id: '12345681', name: 'tenant D', status: 'deactivated', description: '-' },
  { id: '12345682', name: 'tenant E', status: 'active', description: '-' },
];

/* ----------------------------------------
   Summary Sidebar Component
   ---------------------------------------- */

interface SummarySidebarProps {
  sectionStatus: Record<SectionStep, WizardSectionState>;
  onCancel: () => void;
  onCreate: () => void;
  isCreateDisabled: boolean;
}

function SummarySidebar({
  sectionStatus,
  onCancel,
  onCreate,
  isCreateDisabled,
}: SummarySidebarProps) {
  const summaryItems: WizardSummaryItem[] = SECTION_ORDER.map((key) => ({
    key,
    label: SECTION_LABELS[key],
    status: sectionStatus[key],
  }));

  return (
    <div className="w-[312px] shrink-0 sticky top-4 self-start">
      <div className="bg-[var(--color-surface-default)] border border-[var(--color-border-default)] rounded-lg p-4 flex flex-col gap-6">
        <WizardSummary items={summaryItems} />

        {/* Action Buttons */}
        <div className="flex flex-col w-full">
          <div className="flex gap-2 items-center justify-end w-full">
            <Button variant="secondary" onClick={onCancel}>
              Cancel
            </Button>
            <Button
              variant="primary"
              onClick={onCreate}
              disabled={isCreateDisabled}
              className="flex-1"
            >
              Create
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ----------------------------------------
   Main Page Component
   ---------------------------------------- */

export function ComputeAdminCreateImagePage() {
  const navigate = useNavigate();
  const isV2 = useIsV2();
  const [sidebarOpen, setSidebarOpen] = useState(true);

  // Form state
  const [imageName, setImageName] = useState('');
  const [description, setDescription] = useState('');
  const [isProtected, setIsProtected] = useState(false);
  const [visibility, setVisibility] = useState<'public' | 'shared' | 'private'>('public');

  // Owned tenant state
  const [tenantSearch, setTenantSearch] = useState('');
  const [selectedTenantIds, setSelectedTenantIds] = useState<string[]>([]);
  const [tenantCurrentPage, setTenantCurrentPage] = useState(1);
  const tenantRowsPerPage = 5;

  // Shared tenants state (for visibility = shared)
  const [sharedTenantSearch, setSharedTenantSearch] = useState('');
  const [sharedTenantIds, setSharedTenantIds] = useState<string[]>([]);
  const [sharedTenantCurrentPage, setSharedTenantCurrentPage] = useState(1);

  // Source section state
  const [sourceType, setSourceType] = useState<'file' | 'url'>('file');
  const [sourceUrl, setSourceUrl] = useState('');

  // Specification section state
  const [diskFormat, setDiskFormat] = useState('');
  const [os, setOs] = useState('');
  const [osVersion, setOsVersion] = useState('');
  const [osAdmin, setOsAdmin] = useState('');
  const [minDisk, setMinDisk] = useState(0);
  const [minRam, setMinRam] = useState(0);
  const [specAdvancedOpen, setSpecAdvancedOpen] = useState(true);

  // Advanced section state
  const [qemuGuestAgent, setQemuGuestAgent] = useState(true);
  const [cpuPolicy, setCpuPolicy] = useState('none');
  const [cpuThreadPolicy, setCpuThreadPolicy] = useState('none');

  // Section states
  const [sectionStatus, setSectionStatus] = useState<Record<SectionStep, WizardSectionState>>({
    'basic-info': 'active',
    source: isV2 ? 'active' : 'pre',
    specification: isV2 ? 'active' : 'pre',
    advanced: 'done',
  });

  // Validation error state
  const [showTenantError, setShowTenantError] = useState(false);
  const [showImageNameError, setShowImageNameError] = useState(false);
  const [showSourceUrlError, setShowSourceUrlError] = useState(false);
  const [showDiskFormatError, setShowDiskFormatError] = useState(false);
  const [showOsError, setShowOsError] = useState(false);
  const [showOsVersionError, setShowOsVersionError] = useState(false);
  const [showOsAdminError, setShowOsAdminError] = useState(false);

  // Tab management
  const { tabs, activeTabId, closeTab, selectTab, addNewTab, moveTab, updateActiveTabLabel } =
    useTabs();

  // Update tab label
  useEffect(() => {
    updateActiveTabLabel('Create image');
  }, []);

  const tabBarTabs = tabs.map((tab) => ({
    id: tab.id,
    label: tab.label,
    closable: tab.closable,
  }));

  const breadcrumbItems = [
    { label: 'Images', href: '/compute-admin/images' },
    { label: 'Create image' },
  ];

  // Filter tenants by search
  const filteredTenants = useMemo(() => {
    if (!tenantSearch.trim()) return mockTenants;
    return mockTenants.filter(
      (tenant) =>
        tenant.name.toLowerCase().includes(tenantSearch.toLowerCase()) ||
        tenant.id.includes(tenantSearch)
    );
  }, [tenantSearch]);

  const totalTenantPages = Math.ceil(filteredTenants.length / tenantRowsPerPage);
  const paginatedTenants = filteredTenants.slice(
    (tenantCurrentPage - 1) * tenantRowsPerPage,
    tenantCurrentPage * tenantRowsPerPage
  );

  const selectedTenants = mockTenants.filter((t) => selectedTenantIds.includes(t.id));

  // Filter shared tenants by search
  const filteredSharedTenants = useMemo(() => {
    if (!sharedTenantSearch.trim()) return mockTenants;
    return mockTenants.filter(
      (tenant) =>
        tenant.name.toLowerCase().includes(sharedTenantSearch.toLowerCase()) ||
        tenant.id.includes(sharedTenantSearch)
    );
  }, [sharedTenantSearch]);

  const totalSharedTenantPages = Math.ceil(filteredSharedTenants.length / tenantRowsPerPage);
  const paginatedSharedTenants = filteredSharedTenants.slice(
    (sharedTenantCurrentPage - 1) * tenantRowsPerPage,
    sharedTenantCurrentPage * tenantRowsPerPage
  );

  const selectedSharedTenants = mockTenants.filter((t) => sharedTenantIds.includes(t.id));

  // Tenant table columns
  const tenantColumns: TableColumn<Tenant>[] = [
    {
      key: 'status',
      label: 'Status',
      width: fixedColumns.status,
      align: 'center',
      render: (_, row) => <StatusIndicator layout="icon-only" status={row.status} />,
    },
    {
      key: 'name',
      label: 'Name',
      flex: 1,
      sortable: true,
      render: (_, row) => (
        <div className="flex flex-col gap-0.5 min-w-0">
          <div className="flex items-center gap-1">
            <Link
              to={`/compute-admin/tenants/${row.id}`}
              className="text-label-md text-[var(--color-action-primary)] hover:underline hover:underline-offset-2"
              onClick={(e) => e.stopPropagation()}
            >
              {row.name}
            </Link>
            <IconExternalLink size={12} className="text-[var(--color-action-primary)]" />
          </div>
          <span className="text-body-sm text-[var(--color-text-subtle)]">ID: {row.id}</span>
        </div>
      ),
    },
    {
      key: 'description',
      label: 'Description',
      flex: 1,
      sortable: true,
    },
  ];

  // Navigation handlers
  const handleCancel = () => {
    navigate('/compute-admin/images');
  };

  const handleCreate = () => {
    console.log('Creating image:', {
      imageName,
      description,
      isProtected,
      visibility,
      selectedTenantIds,
      sharedTenantIds,
      sourceType,
      sourceUrl,
      diskFormat,
      os,
      osVersion,
      osAdmin,
      minDisk,
      minRam,
      qemuGuestAgent,
      cpuPolicy,
      cpuThreadPolicy,
    });
    navigate('/compute-admin/images');
  };

  // Section navigation
  const goToNextSection = useCallback(
    (currentSection: SectionStep) => {
      // Validate basic-info section
      if (currentSection === 'basic-info') {
        let hasError = false;

        if (!imageName.trim()) {
          setShowImageNameError(true);
          hasError = true;
        } else {
          setShowImageNameError(false);
        }

        if (selectedTenantIds.length === 0) {
          setShowTenantError(true);
          hasError = true;
        } else {
          setShowTenantError(false);
        }

        if (hasError) return;
      }

      // Validate source section
      if (currentSection === 'source') {
        let hasError = false;

        if (sourceType === 'url' && !sourceUrl.trim()) {
          setShowSourceUrlError(true);
          hasError = true;
        } else {
          setShowSourceUrlError(false);
        }

        if (hasError) return;
      }

      // Validate specification section
      if (currentSection === 'specification') {
        let hasError = false;

        if (!diskFormat) {
          setShowDiskFormatError(true);
          hasError = true;
        } else {
          setShowDiskFormatError(false);
        }

        if (!os) {
          setShowOsError(true);
          hasError = true;
        } else {
          setShowOsError(false);
        }

        if (!osVersion.trim()) {
          setShowOsVersionError(true);
          hasError = true;
        } else {
          setShowOsVersionError(false);
        }

        if (!osAdmin.trim()) {
          setShowOsAdminError(true);
          hasError = true;
        } else {
          setShowOsAdminError(false);
        }

        if (hasError) return;
      }

      const currentIndex = SECTION_ORDER.indexOf(currentSection);
      const nextSection = SECTION_ORDER[currentIndex + 1];

      if (nextSection) {
        setSectionStatus((prev) => ({
          ...prev,
          [currentSection]: 'done',
          [nextSection]: 'active',
        }));
      }
    },
    [selectedTenantIds, imageName, sourceType, sourceUrl, diskFormat, os, osVersion, osAdmin, isV2]
  );

  const editSection = useCallback(
    (section: SectionStep) => {
      if (isV2) return;
      setSectionStatus((prev) => {
        const newStatus = { ...prev };
        // Set all sections to their appropriate state
        SECTION_ORDER.forEach((s) => {
          if (s === section) {
            newStatus[s] = 'active';
          } else if (newStatus[s] === 'active') {
            newStatus[s] = 'done';
          }
        });
        return newStatus;
      });
    },
    [isV2]
  );

  // Check if create button should be enabled
  const isCreateDisabled =
    !imageName.trim() ||
    selectedTenantIds.length === 0 ||
    (!isV2 && sectionStatus['basic-info'] === 'active');

  const sidebarWidth = sidebarOpen ? 200 : 0;

  return (
    <PageShell
      sidebar={
        <ComputeAdminSidebar isOpen={sidebarOpen} onToggle={() => setSidebarOpen(!sidebarOpen)} />
      }
      sidebarWidth={sidebarWidth}
      tabBar={
        <TabBar
          tabs={tabBarTabs}
          activeTab={activeTabId}
          onTabChange={selectTab}
          onTabClose={closeTab}
          onTabAdd={addNewTab}
          onTabReorder={moveTab}
          showAddButton={true}
          showWindowControls={true}
        />
      }
      topBar={
        <TopBar
          breadcrumb={<Breadcrumb items={breadcrumbItems} />}
          actions={
            <TopBarAction
              icon={<IconBell size={16} stroke={1.5} />}
              onClick={() => console.log('Notifications clicked')}
              aria-label="Notifications"
              badge
            />
          }
        />
      }
      contentClassName="pt-4 px-8 pb-6"
    >
      <VStack gap={3} className="min-w-[1176px]">
        {/* Page Title */}
        <div className="flex items-center justify-between h-8">
          <h1 className="text-heading-h5 text-[var(--color-text-default)]">Create image</h1>
        </div>

        {/* Content Area */}
        <HStack gap={6} align="start" className="w-full">
          {/* Left Column - Main Content */}
          <VStack gap={4} className="flex-1">
            {/* Basic information Section */}
            <SectionCard isActive={!isV2 && sectionStatus['basic-info'] === 'active'}>
              <SectionCard.Header
                title={SECTION_LABELS['basic-info']}
                showDivider={sectionStatus['basic-info'] === 'done'}
                actions={
                  !isV2 &&
                  sectionStatus['basic-info'] === 'done' && (
                    <Button
                      variant="secondary"
                      size="sm"
                      leftIcon={<IconEdit size={12} />}
                      onClick={() => editSection('basic-info')}
                    >
                      Edit
                    </Button>
                  )
                }
              />
              {sectionStatus['basic-info'] === 'active' && (
                <SectionCard.Content showDividers={false}>
                  <VStack gap={0}>
                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    {/* Image name */}
                    <div className="py-6">
                      <FormField required error={showImageNameError}>
                        <FormField.Label>Image name</FormField.Label>
                        <FormField.Control>
                          <Input
                            value={imageName}
                            onChange={(e) => {
                              setImageName(e.target.value);
                              if (e.target.value.trim()) {
                                setShowImageNameError(false);
                              }
                            }}
                            placeholder="Enter image name"
                            fullWidth
                            error={showImageNameError}
                          />
                        </FormField.Control>
                        {showImageNameError && (
                          <FormField.ErrorMessage>
                            Please enter an image name.
                          </FormField.ErrorMessage>
                        )}
                        <FormField.HelperText>
                          You can use letters, numbers, and special characters (+=,.@-_), and the
                          length must be between 2-128 characters.
                        </FormField.HelperText>
                      </FormField>
                    </div>

                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    {/* Description */}
                    <div className="py-6">
                      <FormField>
                        <FormField.Label>Description</FormField.Label>
                        <FormField.Control>
                          <Input
                            value={description}
                            onChange={(e) => setDescription(e.target.value)}
                            placeholder="Enter description"
                            fullWidth
                          />
                        </FormField.Control>
                        <FormField.HelperText>
                          You can use letters, numbers, and special characters (+=,.@-_()[]), and
                          maximum 255 characters.
                        </FormField.HelperText>
                      </FormField>
                    </div>

                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    {/* Owned tenant section */}
                    <VStack gap={3} className="py-6">
                      <VStack gap={2}>
                        <div className="flex items-center gap-1.5">
                          <span className="text-label-lg leading-[var(--line-height-20)] text-[var(--color-text-default)]">
                            Owned tenant
                          </span>
                          <span className="text-[var(--color-state-danger)]">*</span>
                        </div>
                        <span className="text-body-md text-[var(--color-text-subtle)]">
                          Select the tenant that will own the image.
                        </span>
                      </VStack>

                      {/* Search */}
                      <SearchInput
                        value={tenantSearch}
                        onChange={(e) => setTenantSearch(e.target.value)}
                        placeholder="Search tenants by attributes"
                        className="w-[280px]"
                      />

                      {/* Pagination */}
                      <Pagination
                        currentPage={tenantCurrentPage}
                        totalPages={totalTenantPages}
                        onPageChange={setTenantCurrentPage}
                        totalItems={filteredTenants.length}
                        selectedCount={selectedTenantIds.length}
                      />

                      {/* Tenant Table + Selection Indicator */}
                      <VStack gap={2}>
                        <Table<Tenant>
                          columns={tenantColumns}
                          data={paginatedTenants}
                          rowKey="id"
                          emptyMessage="No tenants found"
                          selectable
                          selectedKeys={selectedTenantIds}
                          onSelectionChange={(keys) => {
                            setSelectedTenantIds(keys);
                            if (keys.length > 0) {
                              setShowTenantError(false);
                            }
                          }}
                        />

                        {/* Selection Indicator */}
                        <SelectionIndicator
                          selectedItems={selectedTenants.map((t) => ({
                            id: t.id,
                            label: `${t.name} (ID: ${t.id})`,
                          }))}
                          onRemove={(id) =>
                            setSelectedTenantIds((prev) => prev.filter((tid) => tid !== id))
                          }
                          error={showTenantError}
                          errorMessage="Please select a tenant."
                        />
                      </VStack>
                    </VStack>

                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    {/* Visibility section */}
                    <VStack gap={3} className="py-6">
                      <VStack gap={2}>
                        <div className="flex items-center gap-1.5">
                          <span className="text-label-lg leading-[var(--line-height-20)] text-[var(--color-text-default)]">
                            Visibility
                          </span>
                          <span className="text-[var(--color-state-danger)]">*</span>
                        </div>
                        <span className="text-body-md text-[var(--color-text-subtle)]">
                          Specifies the availability scope of the image based on its visibility
                          setting.
                        </span>
                      </VStack>
                      {isV2 ? (
                        <VStack gap={6}>
                          {/* Public block */}
                          <div className="border border-[var(--color-border-default)] rounded-[6px] p-4 w-full">
                            <VStack gap={3}>
                              <RadioGroup value="public" onChange={() => {}}>
                                <Radio value="public" label="Public" />
                                <Radio value="shared" label="Shared" />
                                <Radio value="private" label="Private" />
                              </RadioGroup>
                              <span className="text-body-md text-[var(--color-text-subtle)]">
                                The image is available to all tenants.
                              </span>
                            </VStack>
                          </div>

                          {/* Shared block */}
                          <div className="border border-[var(--color-border-default)] rounded-[6px] p-4 w-full">
                            <VStack gap={3}>
                              <RadioGroup value="shared" onChange={() => {}}>
                                <Radio value="public" label="Public" />
                                <Radio value="shared" label="Shared" />
                                <Radio value="private" label="Private" />
                              </RadioGroup>

                              <VStack gap={2}>
                                <span className="text-label-lg text-[var(--color-text-default)]">
                                  Tenants
                                </span>
                                <span className="text-body-md text-[var(--color-text-subtle)]">
                                  Select the tenants to share the image with.
                                </span>
                              </VStack>

                              <SearchInput
                                value={sharedTenantSearch}
                                onChange={(e) => setSharedTenantSearch(e.target.value)}
                                placeholder="Search tenants by attributes"
                                className="w-[280px]"
                              />

                              <Pagination
                                currentPage={sharedTenantCurrentPage}
                                totalPages={totalSharedTenantPages}
                                onPageChange={setSharedTenantCurrentPage}
                                totalItems={filteredSharedTenants.length}
                                selectedCount={sharedTenantIds.length}
                              />

                              <VStack gap={2}>
                                <Table<Tenant>
                                  columns={tenantColumns}
                                  data={paginatedSharedTenants}
                                  rowKey="id"
                                  emptyMessage="No tenants found"
                                  selectable
                                  selectedKeys={sharedTenantIds}
                                  onSelectionChange={(keys) => {
                                    setSharedTenantIds(keys);
                                  }}
                                />
                                <SelectionIndicator
                                  selectedItems={selectedSharedTenants.map((t) => ({
                                    id: t.id,
                                    label: `${t.name} (ID: ${t.id})`,
                                  }))}
                                  onRemove={(id) =>
                                    setSharedTenantIds((prev) => prev.filter((tid) => tid !== id))
                                  }
                                />
                              </VStack>
                            </VStack>
                          </div>

                          {/* Private block */}
                          <div className="border border-[var(--color-border-default)] rounded-[6px] p-4 w-full">
                            <VStack gap={3}>
                              <RadioGroup value="private" onChange={() => {}}>
                                <Radio value="public" label="Public" />
                                <Radio value="shared" label="Shared" />
                                <Radio value="private" label="Private" />
                              </RadioGroup>
                              <span className="text-body-md text-[var(--color-text-subtle)]">
                                The image is only visible to its owner.
                              </span>
                            </VStack>
                          </div>
                        </VStack>
                      ) : (
                        <>
                          <RadioGroup
                            value={visibility}
                            onChange={(val) =>
                              setVisibility(val as 'public' | 'shared' | 'private')
                            }
                          >
                            <Radio value="public" label="Public" />
                            <Radio value="shared" label="Shared" />
                            <Radio value="private" label="Private" />
                          </RadioGroup>

                          {visibility === 'shared' && (
                            <VStack gap={3}>
                              <VStack gap={2}>
                                <span className="text-label-lg text-[var(--color-text-default)]">
                                  Tenants
                                </span>
                                <span className="text-body-md text-[var(--color-text-subtle)]">
                                  Select the tenants to share the image with.
                                </span>
                              </VStack>

                              <SearchInput
                                value={sharedTenantSearch}
                                onChange={(e) => setSharedTenantSearch(e.target.value)}
                                placeholder="Search tenants by attributes"
                                className="w-[280px]"
                              />

                              <Pagination
                                currentPage={sharedTenantCurrentPage}
                                totalPages={totalSharedTenantPages}
                                onPageChange={setSharedTenantCurrentPage}
                                totalItems={filteredSharedTenants.length}
                                selectedCount={sharedTenantIds.length}
                              />

                              <VStack gap={2}>
                                <Table<Tenant>
                                  columns={tenantColumns}
                                  data={paginatedSharedTenants}
                                  rowKey="id"
                                  emptyMessage="No tenants found"
                                  selectable
                                  selectedKeys={sharedTenantIds}
                                  onSelectionChange={(keys) => {
                                    setSharedTenantIds(keys);
                                  }}
                                />
                                <SelectionIndicator
                                  selectedItems={selectedSharedTenants.map((t) => ({
                                    id: t.id,
                                    label: `${t.name} (ID: ${t.id})`,
                                  }))}
                                  onRemove={(id) =>
                                    setSharedTenantIds((prev) => prev.filter((tid) => tid !== id))
                                  }
                                />
                              </VStack>
                            </VStack>
                          )}
                        </>
                      )}
                    </VStack>

                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    {/* Protected */}
                    <div className="py-6">
                      <FormField>
                        <FormField.Label>Protected</FormField.Label>
                        <FormField.Description>
                          Protected images cannot be deleted, preventing accidental removal.
                        </FormField.Description>
                        <FormField.Control className="mt-[var(--primitive-spacing-3)]">
                          <HStack gap={2} align="center">
                            <Toggle checked={isProtected} onChange={setIsProtected} />
                            <span className="text-body-md text-[var(--color-text-default)]">
                              {isProtected ? 'Yes' : 'No'}
                            </span>
                          </HStack>
                        </FormField.Control>
                      </FormField>
                    </div>

                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    <HStack justify="end" className="pt-3">
                      <Button variant="primary" onClick={() => goToNextSection('basic-info')}>
                        Next
                      </Button>
                    </HStack>
                  </VStack>
                </SectionCard.Content>
              )}
              {!isV2 && sectionStatus['basic-info'] === 'done' && (
                <SectionCard.Content>
                  <SectionCard.DataRow label="Image name" value={imageName || '-'} />
                  <SectionCard.DataRow label="Description" value={description || '-'} />
                  <SectionCard.DataRow
                    label="Owned tenant"
                    value={
                      selectedTenants.length > 0
                        ? selectedTenants.map((t) => `${t.name} (ID: ${t.id})`).join(', ')
                        : '-'
                    }
                  />
                  <SectionCard.DataRow
                    label="Visibility"
                    value={visibility.charAt(0).toUpperCase() + visibility.slice(1)}
                  />
                  {visibility === 'shared' && (
                    <SectionCard.DataRow
                      label="Shared with"
                      value={
                        selectedSharedTenants.length > 0
                          ? selectedSharedTenants.map((t) => `${t.name} (ID: ${t.id})`).join(', ')
                          : '-'
                      }
                    />
                  )}
                  <SectionCard.DataRow label="Protected" value={isProtected ? 'Yes' : 'No'} />
                </SectionCard.Content>
              )}
            </SectionCard>

            {isV2 && (
              <SectionCard>
                <SectionCard.Header title={SECTION_LABELS['basic-info']} />
                <SectionCard.Content>
                  <SectionCard.DataRow label="Image name" value={imageName || '-'} />
                  <SectionCard.DataRow label="Description" value={description || '-'} />
                  <SectionCard.DataRow
                    label="Owned tenant"
                    value={
                      selectedTenants.length > 0
                        ? selectedTenants.map((t) => `${t.name} (ID: ${t.id})`).join(', ')
                        : '-'
                    }
                  />
                  <SectionCard.DataRow
                    label="Visibility"
                    value={visibility.charAt(0).toUpperCase() + visibility.slice(1)}
                  />
                  {visibility === 'shared' && (
                    <SectionCard.DataRow
                      label="Shared with"
                      value={
                        selectedSharedTenants.length > 0
                          ? selectedSharedTenants.map((t) => `${t.name} (ID: ${t.id})`).join(', ')
                          : '-'
                      }
                    />
                  )}
                  <SectionCard.DataRow label="Protected" value={isProtected ? 'Yes' : 'No'} />
                </SectionCard.Content>
              </SectionCard>
            )}

            {/* Source Section */}
            <SectionCard isActive={sectionStatus['source'] === 'active'}>
              <SectionCard.Header
                title={SECTION_LABELS['source']}
                showDivider={sectionStatus['source'] === 'done'}
                actions={
                  sectionStatus['source'] === 'done' && (
                    <Button
                      variant="secondary"
                      size="sm"
                      leftIcon={<IconEdit size={12} />}
                      onClick={() => editSection('source')}
                    >
                      Edit
                    </Button>
                  )
                }
              />
              {(isV2 || sectionStatus['source'] === 'active') && (
                <SectionCard.Content showDividers={false}>
                  <VStack gap={0}>
                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    {/* Upload type */}
                    <VStack gap={3} className="py-6">
                      <VStack gap={2}>
                        <div className="flex items-center gap-1.5">
                          <span className="text-label-lg leading-[var(--line-height-20)] text-[var(--color-text-default)]">
                            Upload type
                          </span>
                          <span className="text-[var(--color-state-danger)]">*</span>
                        </div>
                        <span className="text-body-sm leading-[var(--line-height-16)] text-[var(--color-text-subtle)]">
                          Registers an image by uploading a file or entering a file URL.
                        </span>
                      </VStack>

                      {isV2 ? (
                        <VStack gap={6}>
                          {/* Upload file block */}
                          <div className="border border-[var(--color-border-default)] rounded-[6px] p-4 w-full">
                            <VStack gap={3}>
                              <Tabs value="file" onChange={() => {}} variant="underline" size="sm">
                                <TabList>
                                  <Tab value="file">Upload file</Tab>
                                  <Tab value="url">File URL</Tab>
                                </TabList>
                              </Tabs>
                              <VStack gap={3} align="start">
                                <Button
                                  variant="secondary"
                                  size="sm"
                                  leftIcon={<IconUpload size={12} />}
                                >
                                  Choose File
                                </Button>
                                <span className="text-body-sm text-[var(--color-text-subtle)]">
                                  Only RAW, QCOW2, ISO, AKI, and ARI file formats are allowed.
                                </span>
                              </VStack>
                            </VStack>
                          </div>

                          {/* File URL block */}
                          <div className="border border-[var(--color-border-default)] rounded-[6px] p-4 w-full">
                            <VStack gap={3}>
                              <Tabs value="url" onChange={() => {}} variant="underline" size="sm">
                                <TabList>
                                  <Tab value="file">Upload file</Tab>
                                  <Tab value="url">File URL</Tab>
                                </TabList>
                              </Tabs>
                              <VStack gap={2} align="stretch">
                                <Input
                                  value={sourceUrl}
                                  onChange={(e) => {
                                    setSourceUrl(e.target.value);
                                    if (e.target.value.trim()) {
                                      setShowSourceUrlError(false);
                                    }
                                  }}
                                  placeholder="e.g. https://example.com/image.qcow2"
                                  fullWidth
                                  error={showSourceUrlError}
                                />
                                {showSourceUrlError ? (
                                  <span className="text-body-sm text-[var(--color-state-danger)]">
                                    Please enter a file URL.
                                  </span>
                                ) : (
                                  <span className="text-body-sm text-[var(--color-text-subtle)]">
                                    The URL must start with http:// or https://.
                                  </span>
                                )}
                              </VStack>
                            </VStack>
                          </div>
                        </VStack>
                      ) : (
                        <>
                          <Tabs
                            value={sourceType}
                            onChange={(value) => setSourceType(value as 'file' | 'url')}
                            variant="underline"
                            size="sm"
                          >
                            <TabList>
                              <Tab value="file">Upload file</Tab>
                              <Tab value="url">File URL</Tab>
                            </TabList>
                          </Tabs>

                          {sourceType === 'file' && (
                            <VStack gap={3} align="start">
                              <Button
                                variant="secondary"
                                size="sm"
                                leftIcon={<IconUpload size={12} />}
                              >
                                Choose File
                              </Button>
                              <span className="text-body-sm text-[var(--color-text-subtle)]">
                                Only RAW, QCOW2, ISO, AKI, and ARI file formats are allowed.
                              </span>
                            </VStack>
                          )}

                          {sourceType === 'url' && (
                            <VStack gap={2} align="stretch">
                              <Input
                                value={sourceUrl}
                                onChange={(e) => {
                                  setSourceUrl(e.target.value);
                                  if (e.target.value.trim()) {
                                    setShowSourceUrlError(false);
                                  }
                                }}
                                placeholder="e.g. https://example.com/image.qcow2"
                                fullWidth
                                error={showSourceUrlError}
                              />
                              {showSourceUrlError ? (
                                <span className="text-body-sm text-[var(--color-state-danger)]">
                                  Please enter a file URL.
                                </span>
                              ) : (
                                <span className="text-body-sm text-[var(--color-text-subtle)]">
                                  The URL must start with http:// or https://.
                                </span>
                              )}
                            </VStack>
                          )}
                        </>
                      )}
                    </VStack>

                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    <HStack justify="end" className="pt-3">
                      <Button variant="primary" onClick={() => goToNextSection('source')}>
                        Next
                      </Button>
                    </HStack>
                  </VStack>
                </SectionCard.Content>
              )}
              {!isV2 && sectionStatus['source'] === 'done' && (
                <SectionCard.Content>
                  <SectionCard.DataRow
                    label="Upload type"
                    value={sourceType === 'file' ? 'Upload File' : 'File URL'}
                  />
                  {sourceType === 'url' && (
                    <SectionCard.DataRow label="URL" value={sourceUrl || '-'} />
                  )}
                </SectionCard.Content>
              )}
            </SectionCard>

            {isV2 && (
              <SectionCard>
                <SectionCard.Header title={SECTION_LABELS['source']} />
                <SectionCard.Content>
                  <SectionCard.DataRow
                    label="Upload type"
                    value={sourceType === 'file' ? 'Upload File' : 'File URL'}
                  />
                  {sourceType === 'url' && sourceUrl && (
                    <SectionCard.DataRow label="URL" value={sourceUrl} />
                  )}
                </SectionCard.Content>
              </SectionCard>
            )}

            {/* Specification Section */}
            <SectionCard isActive={!isV2 && sectionStatus['specification'] === 'active'}>
              <SectionCard.Header
                title={SECTION_LABELS['specification']}
                showDivider={sectionStatus['specification'] === 'done'}
                actions={
                  !isV2 &&
                  sectionStatus['specification'] === 'done' && (
                    <HStack gap={3} align="center">
                      <span className="text-body-md text-[var(--color-text-subtle)]">
                        Auto-filled
                      </span>
                      <Button
                        variant="secondary"
                        size="sm"
                        leftIcon={<IconEdit size={12} />}
                        onClick={() => editSection('specification')}
                      >
                        Edit
                      </Button>
                    </HStack>
                  )
                }
              />
              {(isV2 || sectionStatus['specification'] === 'active') && (
                <SectionCard.Content showDividers={false}>
                  <VStack gap={0}>
                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    {/* Disk format */}
                    <div className="py-6">
                      <FormField required error={showDiskFormatError}>
                        <FormField.Label>Disk format</FormField.Label>
                        <FormField.Description>
                          Select the disk format for the image. It must match the actual type of the
                          uploaded file.
                        </FormField.Description>
                        <FormField.Control>
                          <Select
                            value={diskFormat}
                            onChange={(value) => {
                              setDiskFormat(value);
                              if (value) setShowDiskFormatError(false);
                            }}
                            placeholder="Select disk format"
                            options={[
                              { value: 'raw', label: 'RAW' },
                              { value: 'qcow2', label: 'QCOW2' },
                              { value: 'vhd', label: 'VHD' },
                              { value: 'vmdk', label: 'VMDK' },
                              { value: 'iso', label: 'ISO' },
                              { value: 'aki', label: 'AKI' },
                              { value: 'ari', label: 'ARI' },
                            ]}
                            fullWidth
                            error={showDiskFormatError}
                          />
                        </FormField.Control>
                        {showDiskFormatError && (
                          <FormField.ErrorMessage>
                            Please select a disk format.
                          </FormField.ErrorMessage>
                        )}
                      </FormField>
                    </div>

                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    {/* OS */}
                    <div className="py-6">
                      <FormField required error={showOsError}>
                        <FormField.Label>OS</FormField.Label>
                        <FormField.Description>
                          Select the operating system type for the image.
                        </FormField.Description>
                        <FormField.Control>
                          <Select
                            value={os}
                            onChange={(value) => {
                              setOs(value);
                              if (value) setShowOsError(false);
                            }}
                            placeholder="Select OS"
                            options={[
                              { value: 'ubuntu', label: 'Ubuntu' },
                              { value: 'centos', label: 'CentOS' },
                              { value: 'debian', label: 'Debian' },
                              { value: 'rhel', label: 'Red Hat Enterprise Linux' },
                              { value: 'windows', label: 'Windows' },
                              { value: 'other', label: 'Other' },
                            ]}
                            fullWidth
                            error={showOsError}
                          />
                        </FormField.Control>
                        {showOsError && (
                          <FormField.ErrorMessage>Please select an OS.</FormField.ErrorMessage>
                        )}
                      </FormField>
                    </div>

                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    {/* OS Version */}
                    <div className="py-6">
                      <FormField required error={showOsVersionError}>
                        <FormField.Label>OS version</FormField.Label>
                        <FormField.Description>
                          This metadata helps categorize image.
                        </FormField.Description>
                        <FormField.Control>
                          <Input
                            value={osVersion}
                            onChange={(e) => {
                              setOsVersion(e.target.value);
                              if (e.target.value.trim()) setShowOsVersionError(false);
                            }}
                            placeholder="e.g. 22.04, 8, 2019"
                            fullWidth
                            error={showOsVersionError}
                          />
                        </FormField.Control>
                        {showOsVersionError && (
                          <FormField.ErrorMessage>
                            Please enter an OS version.
                          </FormField.ErrorMessage>
                        )}
                      </FormField>
                    </div>

                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    {/* OS Admin */}
                    <div className="py-6">
                      <FormField required error={showOsAdminError}>
                        <FormField.Label>OS admin</FormField.Label>
                        <FormField.Description>
                          Enter the default administrator account used when launching instances from
                          this image.
                        </FormField.Description>
                        <FormField.Control>
                          <Input
                            value={osAdmin}
                            onChange={(e) => {
                              setOsAdmin(e.target.value);
                              if (e.target.value.trim()) setShowOsAdminError(false);
                            }}
                            placeholder="e.g. ubuntu(ubuntu), administrator(windows)"
                            fullWidth
                            error={showOsAdminError}
                          />
                        </FormField.Control>
                        {showOsAdminError && (
                          <FormField.ErrorMessage>
                            Please enter an OS admin account.
                          </FormField.ErrorMessage>
                        )}
                      </FormField>
                    </div>

                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    {/* Advanced Section */}
                    <div className="py-6">
                      <Disclosure open={specAdvancedOpen} onChange={setSpecAdvancedOpen}>
                        <DisclosureTrigger>Advanced</DisclosureTrigger>
                        <DisclosurePanel>
                          <VStack gap={4} align="stretch" className="pt-3">
                            {/* Min system Disk */}
                            <FormField
                              label="Min system disk"
                              description="Defines the minimum disk size required to boot an instance from this image."
                            >
                              <HStack gap={3} align="center">
                                <Slider
                                  min={0}
                                  max={500}
                                  step={10}
                                  value={minDisk}
                                  onChange={setMinDisk}
                                />
                                <NumberInput
                                  value={minDisk}
                                  onChange={setMinDisk}
                                  min={0}
                                  max={500}
                                  step={1}
                                  width="xs"
                                  suffix="GiB"
                                />
                              </HStack>
                              <span className="text-body-sm text-[var(--color-text-subtle)]">
                                0-500 GiB
                              </span>
                            </FormField>

                            {/* Min RAM */}
                            <FormField
                              label="Min RAM"
                              description="Defines the minimum amount of RAM required to boot an instance from this image."
                            >
                              <HStack gap={3} align="center">
                                <Slider
                                  min={0}
                                  max={500}
                                  step={10}
                                  value={minRam}
                                  onChange={setMinRam}
                                />
                                <NumberInput
                                  value={minRam}
                                  onChange={setMinRam}
                                  min={0}
                                  max={500}
                                  step={1}
                                  width="xs"
                                  suffix="GiB"
                                />
                              </HStack>
                              <span className="text-body-sm text-[var(--color-text-subtle)]">
                                0-500 GiB
                              </span>
                            </FormField>
                          </VStack>
                        </DisclosurePanel>
                      </Disclosure>
                    </div>

                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    <HStack justify="end" className="pt-3">
                      <Button variant="primary" onClick={() => goToNextSection('specification')}>
                        Next
                      </Button>
                    </HStack>
                  </VStack>
                </SectionCard.Content>
              )}
              {!isV2 && sectionStatus['specification'] === 'done' && (
                <SectionCard.Content>
                  <SectionCard.DataRow
                    label="Disk format"
                    value={diskFormat ? diskFormat.toUpperCase() : '-'}
                  />
                  <SectionCard.DataRow label="OS" value={os || '-'} />
                  <SectionCard.DataRow label="OS Version" value={osVersion || '-'} />
                  <SectionCard.DataRow label="OS Admin" value={osAdmin || '-'} />
                  <SectionCard.DataRow label="Min system Disk" value={`${minDisk} GiB`} />
                  <SectionCard.DataRow label="Min RAM" value={`${minRam} GiB`} />
                </SectionCard.Content>
              )}
            </SectionCard>

            {isV2 && (
              <SectionCard>
                <SectionCard.Header title={SECTION_LABELS['specification']} />
                <SectionCard.Content>
                  <SectionCard.DataRow
                    label="Disk format"
                    value={diskFormat ? diskFormat.toUpperCase() : '-'}
                  />
                  <SectionCard.DataRow label="OS" value={os || '-'} />
                  <SectionCard.DataRow label="OS Version" value={osVersion || '-'} />
                  <SectionCard.DataRow label="OS Admin" value={osAdmin || '-'} />
                  <SectionCard.DataRow label="Min system Disk" value={`${minDisk} GiB`} />
                  <SectionCard.DataRow label="Min RAM" value={`${minRam} GiB`} />
                </SectionCard.Content>
              </SectionCard>
            )}

            {/* Advanced Section */}
            <SectionCard isActive={!isV2 && sectionStatus['advanced'] === 'active'}>
              <SectionCard.Header
                title={SECTION_LABELS['advanced']}
                showDivider={false}
                actions={
                  !isV2 &&
                  sectionStatus['advanced'] === 'done' && (
                    <HStack gap={3} align="center">
                      <span className="text-body-md text-[var(--color-text-subtle)]">
                        Auto-filled
                      </span>
                      <Button
                        variant="secondary"
                        size="sm"
                        leftIcon={<IconEdit size={12} />}
                        onClick={() => editSection('advanced')}
                      >
                        Edit
                      </Button>
                    </HStack>
                  )
                }
              />
              {(isV2 || sectionStatus['advanced'] === 'active') && (
                <SectionCard.Content showDividers={false}>
                  <VStack gap={0}>
                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    {/* QEMU Guest Agent */}
                    <div className="py-6">
                      <FormField>
                        <FormField.Label>QEMU guest agent</FormField.Label>
                        <FormField.Description>
                          Enables communication and status retrieval between the hypervisor and the
                          instance.
                        </FormField.Description>
                        <FormField.Control className="mt-[var(--primitive-spacing-3)]">
                          <HStack gap={2} align="center">
                            <Toggle checked={qemuGuestAgent} onChange={setQemuGuestAgent} />
                            <span className="text-body-md text-[var(--color-text-default)]">
                              {qemuGuestAgent ? 'On' : 'Off'}
                            </span>
                          </HStack>
                        </FormField.Control>
                      </FormField>
                    </div>

                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    {/* CPU Policy */}
                    <div className="py-6">
                      <FormField>
                        <FormField.Label>CPU policy</FormField.Label>
                        <FormField.Description>
                          Policy that defines how vCPUs are allocated.
                        </FormField.Description>
                        <FormField.Control>
                          <Select
                            value={cpuPolicy}
                            onChange={(value) => setCpuPolicy(value)}
                            options={[
                              { value: 'none', label: 'None' },
                              { value: 'dedicated', label: 'Dedicated' },
                              { value: 'shared', label: 'Shared' },
                            ]}
                            fullWidth
                          />
                        </FormField.Control>
                      </FormField>
                    </div>

                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    {/* CPU Thread Policy */}
                    <div className="py-6">
                      <FormField>
                        <FormField.Label>CPU thread policy</FormField.Label>
                        <FormField.Description>
                          Policy defining how hyperthreads are used for vCPU placement.
                        </FormField.Description>
                        <FormField.Control>
                          <Select
                            value={cpuThreadPolicy}
                            onChange={(value) => setCpuThreadPolicy(value)}
                            options={[
                              { value: 'none', label: 'None' },
                              { value: 'prefer', label: 'Prefer' },
                              { value: 'isolate', label: 'Isolate' },
                              { value: 'require', label: 'Require' },
                            ]}
                            fullWidth
                          />
                        </FormField.Control>
                      </FormField>
                    </div>

                    <div className="w-full h-px bg-[var(--color-border-subtle)]" />

                    <HStack justify="end" gap={2} className="pt-3">
                      <Button
                        variant="secondary"
                        onClick={() => {
                          // Reset to default values
                          setQemuGuestAgent(true);
                          setCpuPolicy('none');
                          setCpuThreadPolicy('none');
                        }}
                      >
                        Cancel
                      </Button>
                      <Button
                        variant="primary"
                        onClick={() => {
                          setSectionStatus((prev) => ({
                            ...prev,
                            advanced: 'done',
                          }));
                        }}
                      >
                        Done
                      </Button>
                    </HStack>
                  </VStack>
                </SectionCard.Content>
              )}
              {!isV2 && sectionStatus['advanced'] === 'done' && (
                <SectionCard.Content>
                  <SectionCard.DataRow
                    label="QEMU Guest Agent"
                    value={qemuGuestAgent ? 'On' : 'Off'}
                  />
                  <SectionCard.DataRow
                    label="CPU Policy"
                    value={
                      cpuPolicy === 'none'
                        ? 'None'
                        : cpuPolicy.charAt(0).toUpperCase() + cpuPolicy.slice(1)
                    }
                  />
                  <SectionCard.DataRow
                    label="CPU Thread Policy"
                    value={
                      cpuThreadPolicy === 'none'
                        ? 'None'
                        : cpuThreadPolicy.charAt(0).toUpperCase() + cpuThreadPolicy.slice(1)
                    }
                  />
                </SectionCard.Content>
              )}
            </SectionCard>

            {isV2 && (
              <SectionCard>
                <SectionCard.Header title={SECTION_LABELS['advanced']} />
                <SectionCard.Content>
                  <SectionCard.DataRow
                    label="QEMU Guest Agent"
                    value={qemuGuestAgent ? 'On' : 'Off'}
                  />
                  <SectionCard.DataRow
                    label="CPU Policy"
                    value={
                      cpuPolicy === 'none'
                        ? 'None'
                        : cpuPolicy.charAt(0).toUpperCase() + cpuPolicy.slice(1)
                    }
                  />
                  <SectionCard.DataRow
                    label="CPU Thread Policy"
                    value={
                      cpuThreadPolicy === 'none'
                        ? 'None'
                        : cpuThreadPolicy.charAt(0).toUpperCase() + cpuThreadPolicy.slice(1)
                    }
                  />
                </SectionCard.Content>
              </SectionCard>
            )}
          </VStack>

          {/* Right Column - Summary Sidebar */}
          <SummarySidebar
            sectionStatus={sectionStatus}
            onCancel={handleCancel}
            onCreate={handleCreate}
            isCreateDisabled={isCreateDisabled}
          />
        </HStack>

        {isV2 && (
          <HStack justify="end" gap={2} className="pt-4">
            <Button variant="secondary" onClick={handleCancel}>
              Cancel
            </Button>
            <Button variant="primary" onClick={handleCreate} disabled={isCreateDisabled}>
              Create
            </Button>
          </HStack>
        )}
      </VStack>
    </PageShell>
  );
}

export default ComputeAdminCreateImagePage;
